        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.LOAD_DATE
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_recruiterdepartments_departments') }} l
INNER JOIN {{ ref('lks_erc_recruiterdepartments_departments_curr') }} ls
    ON l.LNK_RECRUITERDEPARTMENTS_DEPARTMENTS_HKEY = ls.LNK_RECRUITERDEPARTMENTS_DEPARTMENTS_HKEY
)

